#!/usr/bin/env python3
import sys, os, re, csv, json, sqlite3, gzip, bz2, lzma, io, time
from typing import List, Dict, Any, Tuple, Optional

USAGE = '''trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN.

Usage
\ttrdsql [OPTIONS] [SQL(SELECT...)]

Options:
  -A string           analyze the file but only suggest SQL.
  -a string           analyze the file and suggest SQL.
  -config string      configuration file location.
  -db string          specify db name of the setting.
  -dblist             display db information.
  -debug              debug print.
  -driver string      database driver.  [ mysql | postgres | sqlite3 | sqlite3_ext ]
  -dsn string         database driver specific data source name.
  -help               display usage information.
  -q string           read query from the specified file.
  -t string           read table name from the specified file.
  -version            display version information.

Input Formats:
  -icsv               CSV format for input.
  -ig                 guess format from extension. (default "true")
  -ijson              JSON format for input.
  -iltsv              LTSV format for input.
  -itbln              TBLN format for input.
  -itext              text format for input.
  -iwidth             width specification format for input.
  -iyaml              YAML format for input.

Input options:
  -id string          field delimiter for input. (default ",")
  -ih                 the first line is interpreted as column names(CSV only).
  -ijq string         jq expression string for input(JSON/JSONL only).
  -ilr int            limited number of rows to read. (default 0)
  -inull value        value(string) to convert to null on input.
  -inum               add row number column.
  -ir int             number of rows to preread. (default 1)
  -is int             skip header row. (default 0)

Output Formats:
  -oat                ASCII Table format for output.
  -ocsv               CSV format for output.
  -ojson              JSON format for output.
  -ojsonl             JSON lines format for output.
  -oltsv              LTSV format for output.
  -omd                Markdown format for output.
  -oraw               Raw format for output.
  -otbln              TBLN format for output.
  -ovf                Vertical format for output.
  -oyaml              YAML format for output.

Output options:
  -oaq                enclose all fields in quotes for output.
  -ocrlf              use CRLF for output. End each output line with '\\r\\n' instead of '\\n'.
  -od string          field delimiter for output. (default ",")
  -oh                 output column name as header.
  -onowrap            do not wrap long lines(at/md only).
  -onull value        value(string) to convert from null on output.
  -oq string          quote character for output. (default "\\\"")
  -out string         output file name.
  -out-without-guess  output without guessing (when using -out).
  -oz string          output compression format. [ gz | bz2 | zstd | lz4 | xz ]

Examples:
  $ trdsql "SELECT c1,c2 FROM test.csv"
  $ trdsql -oltsv "SELECT c1,c2 FROM test.json::.items"
  $ cat test.csv | trdsql -icsv -oltsv "SELECT c1,c2 FROM -"
'''

BOOL_FLAGS = set('help version dblist debug icsv ig ijson iltsv itbln itext iwidth iyaml ih inum oat ocsv ojson ojsonl oltsv omd oraw otbln ovf oyaml oaq ocrlf oh onowrap out-without-guess'.split())
STR_FLAGS = set('A a config db driver dsn q t id ijq inull onull od oq out oz'.split())
INT_FLAGS = set('ilr ir is'.split())
INPUT_FORMAT_FLAGS = {'icsv':'csv','ijson':'json','iltsv':'ltsv','itbln':'tbln','itext':'text','iwidth':'width','iyaml':'yaml'}
OUTPUT_FORMAT_FLAGS = {'oat':'at','ocsv':'csv','ojson':'json','ojsonl':'jsonl','oltsv':'ltsv','omd':'md','oraw':'raw','otbln':'tbln','ovf':'vf','oyaml':'yaml'}

class Opt:
    def __init__(self):
        self.bool = {k: False for k in BOOL_FLAGS}
        self.bool['ig'] = True
        self.str = {'id': ',', 'od': ',', 'oq': '"'}
        for k in STR_FLAGS:
            self.str.setdefault(k, '')
        self.integer = {'ilr':0,'ir':1,'is':0}
        self.args: List[str] = []
        self.input_format: Optional[str] = None
        self.output_format: Optional[str] = None
        self.output_explicit = False
        self.itext_explicit = False


def print_usage(stream):
    stream.write(USAGE)


def parse_bool_value(v: str) -> bool:
    return v.lower() not in ('0','false','f','no','n')


def parse_args(argv: List[str]) -> Tuple[Optional[Opt], int]:
    opt = Opt()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            opt.args.extend(argv[i+1:])
            break
        if a.startswith('-') and a != '-':
            raw = a[2:] if a.startswith('--') else a[1:]
            val = None
            if '=' in raw:
                raw, val = raw.split('=',1)
            name = raw
            if name == 'h':
                print_usage(sys.stderr)
                return None, 0
            if name in BOOL_FLAGS:
                b = True if val is None else parse_bool_value(val)
                opt.bool[name] = b
                if b and name in INPUT_FORMAT_FLAGS:
                    opt.input_format = INPUT_FORMAT_FLAGS[name]
                    if name == 'itext': opt.itext_explicit = True
                if b and name in OUTPUT_FORMAT_FLAGS:
                    opt.output_format = OUTPUT_FORMAT_FLAGS[name]
                    opt.output_explicit = True
                i += 1
                continue
            if name in STR_FLAGS:
                if val is None:
                    if i+1 >= len(argv):
                        sys.stderr.write(f'flag needs an argument: -{name}\n')
                        print_usage(sys.stderr)
                        return None, 2
                    val = argv[i+1]
                    i += 1
                opt.str[name] = val
                i += 1
                continue
            if name in INT_FLAGS:
                if val is None:
                    if i+1 >= len(argv):
                        sys.stderr.write(f'flag needs an argument: -{name}\n')
                        print_usage(sys.stderr)
                        return None, 2
                    val = argv[i+1]
                    i += 1
                try:
                    opt.integer[name] = int(val)
                except Exception:
                    sys.stderr.write(f'invalid value "{val}" for flag -{name}: parse error\n')
                    return None, 2
                i += 1
                continue
            sys.stderr.write(f'flag provided but not defined: -{name}\n')
            print_usage(sys.stderr)
            return None, 2
        else:
            opt.args.append(a)
            i += 1
    return opt, -1


def nowlog() -> str:
    return time.strftime('%Y/%m/%d %H:%M:%S')


def qident(s: str) -> str:
    return '"' + s.replace('"','""') + '"'


def split_table_spec(spec: str) -> Tuple[str, str]:
    if '::' in spec:
        f, jq = spec.split('::',1)
        return f, jq
    return spec, ''


def guess_format(path: str, opt: Opt) -> str:
    if opt.input_format:
        return opt.input_format
    p = path.lower()
    # compression suffix is not handled for input, but strip common one for guessing
    for suf in ('.gz','.bz2','.xz'):
        if p.endswith(suf): p = p[:-len(suf)]
    if p.endswith('.ltsv'): return 'ltsv'
    if p.endswith('.json') or p.endswith('.jsonl') or p.endswith('.ndjson'): return 'json'
    if p.endswith('.yaml') or p.endswith('.yml'): return 'yaml'
    if p.endswith('.tbln'): return 'tbln'
    if p.endswith('.tsv') or p.endswith('.tab'): return 'csv'
    if p.endswith('.txt') or p.endswith('.log'): return 'text'
    return 'csv'


def read_text_file(path: str) -> str:
    if path == '-':
        return sys.stdin.read()
    # transparent read for common compression formats
    if path.endswith('.gz'):
        with gzip.open(path, 'rt', newline='') as f: return f.read()
    if path.endswith('.bz2'):
        with bz2.open(path, 'rt', newline='') as f: return f.read()
    if path.endswith('.xz'):
        with lzma.open(path, 'rt', newline='') as f: return f.read()
    with open(path, 'r', newline='') as f:
        return f.read()


def apply_inull(v: Any, opt: Opt) -> Any:
    if v is None: return None
    s = str(v)
    if opt.str.get('inull','') != '' and s == opt.str.get('inull'):
        return None
    return s


def make_columns(n: int) -> List[str]:
    return [f'c{i}' for i in range(1,n+1)]


def normalize_rows(cols: List[str], rows: List[List[Any]]) -> List[List[Any]]:
    n = len(cols)
    out=[]
    for r in rows:
        rr = list(r[:n]) + ['']*max(0,n-len(r))
        out.append(rr)
    return out


def parse_csv_data(path: str, content: str, opt: Opt) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    delim = opt.str.get('id', ',') or ','
    if delim == '\\t': delim = '\t'
    if path.lower().endswith(('.tsv','.tab')) and opt.str.get('id', ',') == ',' and opt.input_format is None:
        delim = '\t'
    rdr = csv.reader(io.StringIO(content), delimiter=delim, quotechar='"')
    raw = [row for row in rdr if len(row) > 0]
    skip = max(0,opt.integer.get('is',0))
    if skip:
        raw = raw[skip:]
    if opt.bool.get('ih'):
        if raw:
            cols = [c if c != '' else f'c{i+1}' for i,c in enumerate(raw[0])]
            data = raw[1:]
        else:
            cols=[]; data=[]
    else:
        n = max([len(r) for r in raw], default=0)
        cols = make_columns(n)
        data = raw
    if opt.bool.get('inum'):
        cols = ['num'] + cols
    limit = opt.integer.get('ilr',0)
    rows=[]
    for idx,r in enumerate(data, start=1):
        if limit and len(rows) >= limit: break
        vals = [apply_inull(x,opt) for x in r]
        if opt.bool.get('inum'):
            vals = [str(idx)] + vals
        rows.append(vals)
    rows = normalize_rows(cols, rows)
    return cols, rows, {c:'text' for c in cols}


def parse_ltsv(content: str, opt: Opt) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    cols=[]; rows=[]; limit=opt.integer.get('ilr',0); idx=0
    for line in content.splitlines():
        if line == '': continue
        rec={}
        for part in line.split('\t'):
            if ':' in part:
                k,v = part.split(':',1)
                if k not in cols: cols.append(k)
                rec[k] = apply_inull(v,opt)
        idx += 1
        if opt.bool.get('inum') and 'num' not in cols:
            cols = ['num'] + cols
        row = []
        for c in cols:
            if c == 'num' and opt.bool.get('inum'):
                row.append(str(idx))
            else:
                row.append(rec.get(c,''))
        rows.append(row)
        if limit and len(rows) >= limit: break
    rows = normalize_rows(cols, rows)
    return cols, rows, {c:'text' for c in cols}


def json_scalar_to_cell(v: Any, opt: Opt) -> Any:
    if v is None:
        return None
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int,float)):
        return apply_inull(str(v), opt)
    if isinstance(v, (dict,list)):
        return apply_inull(json.dumps(v, ensure_ascii=False, separators=(',', ':'), sort_keys=True), opt)
    return apply_inull(str(v), opt)


def jq_select(data: Any, expr: str) -> Any:
    if not expr: return data
    e = expr.strip()
    if e.startswith('.'): e = e[1:]
    if e == '': return data
    cur = data
    # small subset: .a.b, .items[0]
    parts=[]
    for p in e.split('.'):
        if p: parts.append(p)
    for p in parts:
        m = re.fullmatch(r'([^\[]+)(?:\[(\d+)\])?', p)
        if not m: return cur
        key, idx = m.group(1), m.group(2)
        if isinstance(cur, dict):
            cur = cur.get(key)
        else:
            return None
        if idx is not None and isinstance(cur, list):
            j=int(idx); cur = cur[j] if 0 <= j < len(cur) else None
    return cur


def parse_json_data(content: str, jqexpr: str, opt: Opt) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    text = content.strip()
    data = None
    if not text:
        data=[]
    else:
        try:
            data = json.loads(text)
        except Exception:
            # JSON lines
            arr=[]
            for line in content.splitlines():
                if line.strip(): arr.append(json.loads(line))
            data=arr
    data = jq_select(data, jqexpr or opt.str.get('ijq',''))
    if isinstance(data, list):
        records = data
    else:
        records = [data]
    cols=[]
    for rec in records:
        if isinstance(rec, dict):
            for k in rec.keys():
                if k not in cols: cols.append(str(k))
        else:
            if 'c1' not in cols: cols.append('c1')
    if opt.bool.get('inum'):
        cols = ['num'] + cols
    rows=[]; limit=opt.integer.get('ilr',0)
    for idx,rec in enumerate(records, start=1):
        if limit and len(rows) >= limit: break
        row=[]
        for c in cols:
            if c == 'num' and opt.bool.get('inum'):
                row.append(str(idx)); continue
            if isinstance(rec, dict):
                row.append(json_scalar_to_cell(rec.get(c), opt) if c in rec else '')
            else:
                row.append(json_scalar_to_cell(rec, opt) if c == 'c1' else '')
        rows.append(row)
    return cols, rows, {c:'text' for c in cols}


def parse_yaml_value(v: str) -> Any:
    v = v.strip()
    if v == '' or v in ('null','Null','NULL','~'):
        return None
    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
        return v[1:-1]
    return v


def parse_yaml_data(content: str, opt: Opt) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    records=[]
    cur=None
    lines=content.splitlines()
    for line in lines:
        if not line.strip(): continue
        if line.strip() == '---':
            if cur is not None:
                records.append(cur); cur=None
            continue
        stripped=line.strip()
        if stripped.startswith('- '):
            if cur is not None: records.append(cur)
            cur={}
            rest=stripped[2:].strip()
            if rest and ':' in rest:
                k,v=rest.split(':',1); cur[k.strip()]=parse_yaml_value(v)
        elif ':' in stripped:
            if cur is None: cur={}
            k,v=stripped.split(':',1); cur[k.strip()]=parse_yaml_value(v)
    if cur is not None: records.append(cur)
    cols=[]
    for r in records:
        for k in r.keys():
            if k not in cols: cols.append(k)
    if opt.bool.get('inum'):
        cols=['num']+cols
    rows=[]; limit=opt.integer.get('ilr',0)
    for idx,r in enumerate(records, start=1):
        if limit and len(rows)>=limit: break
        row=[]
        for c in cols:
            if c=='num' and opt.bool.get('inum'): row.append(str(idx))
            else: row.append(apply_inull(r.get(c,''), opt) if c in r else '')
        rows.append(row)
    return cols, rows, {c:'text' for c in cols}


def tbln_cells(line: str) -> List[str]:
    if '|' not in line: return []
    parts=line.split('|')
    # drop text before first and after last
    return [p.strip() for p in parts[1:-1]]


def parse_tbln(content: str, opt: Opt) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    cols=[]; types=[]; rows=[]
    for line in content.splitlines():
        s=line.strip()
        if not s: continue
        if s.startswith(';') and 'name:' in s:
            cols=tbln_cells(s)
        elif s.startswith(';') and 'type:' in s:
            types=tbln_cells(s)
        elif s.startswith('|'):
            rows.append(tbln_cells(s))
    if not cols and rows:
        cols=make_columns(max(len(r) for r in rows))
    typemap={}
    for i,c in enumerate(cols):
        t=(types[i] if i < len(types) else 'text').lower()
        if t in ('int','integer'): typemap[c]='integer'
        elif t in ('real','float','double'): typemap[c]='real'
        else: typemap[c]='text'
    out=[]; limit=opt.integer.get('ilr',0)
    for r in rows:
        if limit and len(out)>=limit: break
        rr=[]
        for i,c in enumerate(cols):
            v = r[i] if i < len(r) else ''
            v = apply_inull(v,opt)
            if v is not None:
                try:
                    if typemap.get(c)=='integer': v=int(v)
                    elif typemap.get(c)=='real': v=float(v)
                except Exception:
                    pass
            rr.append(v)
        out.append(rr)
    return cols, out, typemap


def parse_text_data(content: str, opt: Opt, explicit: bool) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    lines = content.splitlines()
    if not explicit:
        lines = [l for l in lines if l != '']
    limit=opt.integer.get('ilr',0)
    rows=[]
    for idx,l in enumerate(lines, start=1):
        if limit and len(rows)>=limit: break
        if opt.bool.get('inum'):
            rows.append([str(idx), apply_inull(l,opt)])
        else:
            rows.append([apply_inull(l,opt)])
    cols=['num','text'] if opt.bool.get('inum') else ['text']
    return cols, rows, {c:'text' for c in cols}


def load_data_for_spec(spec: str, opt: Opt) -> Tuple[List[str], List[List[Any]], Dict[str,str]]:
    path, jq = split_table_spec(spec)
    fmt = guess_format(path, opt)
    content = read_text_file(path)
    if fmt == 'ltsv': return parse_ltsv(content, opt)
    if fmt == 'json': return parse_json_data(content, jq, opt)
    if fmt == 'yaml': return parse_yaml_data(content, opt)
    if fmt == 'tbln': return parse_tbln(content, opt)
    if fmt == 'text': return parse_text_data(content, opt, opt.itext_explicit)
    if fmt == 'width':
        # Minimal support: fixed-width mode treats non-empty lines after the first as one field.
        lines=[l.rstrip('\n') for l in content.splitlines()]
        if lines: lines=lines[1:]
        return ['text'], [[apply_inull(l,opt)] for l in lines if l!=''], {'text':'text'}
    return parse_csv_data(path, content, opt)


def create_table(conn: sqlite3.Connection, table: str, cols: List[str], rows: List[List[Any]], types: Dict[str,str]):
    if not cols:
        cols=['c1']
    defs=[]
    for c in cols:
        typ = types.get(c,'text').upper()
        if typ not in ('INTEGER','REAL','TEXT'): typ='TEXT'
        defs.append(f'{qident(c)} {typ}')
    conn.execute(f'CREATE TABLE {qident(table)} ({", ".join(defs)})')
    if rows:
        ph=','.join(['?']*len(cols))
        conn.executemany(f'INSERT INTO {qident(table)} VALUES ({ph})', normalize_rows(cols, rows))


def read_token(sql: str, start: int) -> Tuple[str,int,int,bool]:
    n=len(sql); i=start
    while i<n and sql[i].isspace(): i+=1
    if i>=n: return '',i,i,False
    if sql[i] in ('`','"',"'"):
        q=sql[i]; j=i+1
        while j<n:
            if sql[j]==q:
                if j+1<n and sql[j+1]==q:
                    j+=2; continue
                break
            j+=1
        tok=sql[i+1:j]
        return tok,i,min(j+1,n),True
    j=i
    while j<n and (not sql[j].isspace()) and sql[j] not in ',;)':
        j+=1
    return sql[i:j],i,j,False


def extract_and_rewrite(sql: str, conn: sqlite3.Connection, opt: Opt) -> Tuple[str, Dict[str,str], Dict[str,str]]:
    pieces=[]; last=0; mapping={}; source_types={}
    count=0
    for m in re.finditer(r'(?i)\b(FROM|JOIN)\s+', sql):
        tok, s, e, quoted = read_token(sql, m.end())
        if not tok or tok.startswith('('):
            continue
        spec = tok
        path,_ = split_table_spec(spec)
        should_load = (path == '-' or os.path.exists(path))
        if should_load:
            if spec not in mapping:
                count += 1
                tname = f'__trdsql_{count}'
                try:
                    cols, rows, types = load_data_for_spec(spec, opt)
                    create_table(conn, tname, cols, rows, types)
                    for c,t in types.items():
                        source_types.setdefault(c,t)
                except Exception as ex:
                    raise RuntimeError('import: ' + str(ex))
                mapping[spec]=tname
            pieces.append(sql[last:s])
            pieces.append(mapping[spec])
            last=e
    if not pieces:
        return sql, mapping, source_types
    pieces.append(sql[last:])
    return ''.join(pieces), mapping, source_types


def cell_to_str(v: Any, opt: Opt) -> str:
    if v is None:
        return opt.str.get('onull','')
    if isinstance(v, bytes):
        try: return v.decode()
        except Exception: return str(v)
    return str(v)


def fetch_query(sql: str, opt: Opt) -> Tuple[List[str], List[Tuple[Any,...]], Dict[str,str], str]:
    conn=sqlite3.connect(':memory:')
    conn.row_factory = None
    source_types={}
    try:
        rewritten, mapping, source_types = extract_and_rewrite(sql, conn, opt)
    except RuntimeError:
        conn.close(); raise
    try:
        cur=conn.execute(rewritten)
        cols=[d[0] for d in (cur.description or [])]
        rows=cur.fetchall() if cur.description else []
        conn.close()
        return cols, rows, source_types, rewritten
    except sqlite3.Error as ex:
        conn.close()
        raise RuntimeError(f'export: {ex} [{sql}]')


def csv_output(cols, rows, opt: Opt, include_header: bool) -> str:
    out=io.StringIO(newline='')
    delim=opt.str.get('od', ',') or ','
    if delim == '\\t': delim='\t'
    q=opt.str.get('oq','"') or '"'
    lineterm='\r\n' if opt.bool.get('ocrlf') else '\n'
    writer=csv.writer(out, delimiter=delim, quotechar=q[0], lineterminator=lineterm, quoting=csv.QUOTE_ALL if opt.bool.get('oaq') else csv.QUOTE_MINIMAL, doublequote=True)
    if include_header:
        writer.writerow(cols)
    for r in rows:
        writer.writerow([cell_to_str(v,opt) for v in r])
    return out.getvalue()


def raw_output(cols, rows, opt: Opt, include_header: bool) -> str:
    delim=opt.str.get('od', ',') or ','
    if delim == '\\t': delim='\t'
    lines=[]
    if include_header: lines.append(delim.join(cols))
    for r in rows: lines.append(delim.join(cell_to_str(v,opt) for v in r))
    return '\n'.join(lines) + ('\n' if lines else '')


def ltsv_output(cols, rows, opt: Opt) -> str:
    lines=[]
    for r in rows:
        lines.append('\t'.join(f'{cols[i]}:{cell_to_str(r[i] if i<len(r) else None,opt)}' for i in range(len(cols))))
    return '\n'.join(lines) + ('\n' if lines else '')


def jsonable(v: Any, opt: Opt) -> Any:
    if v is None: return None
    return v


def json_output(cols, rows, opt: Opt, lines: bool=False) -> str:
    objs=[]
    for r in rows:
        obj={}
        for i,c in enumerate(cols): obj[c]=jsonable(r[i] if i<len(r) else None,opt)
        objs.append(obj)
    if lines:
        return ''.join(json.dumps(o, ensure_ascii=False, separators=(',', ':'))+'\n' for o in objs)
    return json.dumps(objs, ensure_ascii=False, indent=2) + '\n'


def yaml_scalar(v: Any, opt: Opt) -> str:
    if v is None: return 'null'
    s=str(v)
    if s == '' or s.lower() == 'null': return 'null'
    return s


def yaml_output(cols, rows, opt: Opt) -> str:
    lines=[]
    for r in rows:
        if not cols: continue
        lines.append(f'- {cols[0]}: {yaml_scalar(r[0] if r else None,opt)}')
        for i,c in enumerate(cols[1:], start=1):
            lines.append(f'  {c}: {yaml_scalar(r[i] if i<len(r) else None,opt)}')
    return '\n'.join(lines) + ('\n' if lines else '')


def is_numlike(s: str) -> bool:
    return bool(re.fullmatch(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?', s.strip()))


def center(s: str, w: int) -> str:
    if len(s) >= w: return s
    total=w-len(s); left=total//2; right=total-left
    return ' '*left + s + ' '*right


def at_md_output(cols, rows, opt: Opt, md=False) -> str:
    vals=[[cell_to_str(v,opt) for v in r] for r in rows]
    widths=[]
    for i,c in enumerate(cols):
        mx=len(c)
        for r in vals:
            if i<len(r): mx=max(mx,len(r[i]))
        widths.append(mx)
    def sep(ch='-'):
        if md:
            return '|' + '|'.join(ch*(w+2) for w in widths) + '|'
        return '+' + '+'.join(ch*(w+2) for w in widths) + '+'
    def row_line(cells, header=False):
        parts=[]
        for i in range(len(cols)):
            s=cells[i] if i < len(cells) else ''
            if header:
                body=center(s,widths[i])
            elif is_numlike(s):
                body=s.rjust(widths[i])
            else:
                body=s.ljust(widths[i])
            parts.append(' '+body+' ')
        return '|' + '|'.join(parts) + '|'
    lines=[]
    if not md: lines.append(sep())
    lines.append(row_line(cols, True))
    lines.append(sep())
    for r in vals: lines.append(row_line(r, False))
    if not md: lines.append(sep())
    return '\n'.join(lines)+'\n'


def vf_output(cols, rows, opt: Opt) -> str:
    vals=[[cell_to_str(v,opt) for v in r] for r in rows]
    w=max([len(c) for c in cols], default=0)
    lines=[]
    for idx,r in enumerate(vals, start=1):
        lines.append(f'---[{idx:2d}]------------------------')
        for i,c in enumerate(cols):
            lines.append('  '+c.rjust(w)+' | '+(r[i] if i<len(r) else ''))
    return '\n'.join(lines)+'\n' if lines else ''


def tbln_output(cols, rows, opt: Opt, source_types: Dict[str,str]) -> str:
    typ=[]
    for c in cols:
        t=source_types.get(c,'text').lower()
        typ.append('int' if t in ('integer','int') else ('real' if t=='real' else 'text'))
    lines=[]
    lines.append('; name: | ' + ' | '.join(cols) + ' |')
    lines.append('; type: | ' + ' | '.join(typ) + ' |')
    for r in rows:
        lines.append('| ' + ' | '.join(cell_to_str(r[i] if i<len(r) else None,opt) for i in range(len(cols))) + ' |')
    return '\n'.join(lines)+'\n'


def render(cols, rows, opt: Opt, source_types: Dict[str,str]) -> str:
    fmt=opt.output_format or 'csv'
    if fmt=='csv': return csv_output(cols, rows, opt, opt.bool.get('oh'))
    if fmt=='raw': return raw_output(cols, rows, opt, opt.bool.get('oh'))
    if fmt=='ltsv': return ltsv_output(cols, rows, opt)
    if fmt=='json': return json_output(cols, rows, opt, False)
    if fmt=='jsonl': return json_output(cols, rows, opt, True)
    if fmt=='yaml': return yaml_output(cols, rows, opt)
    if fmt=='tbln': return tbln_output(cols, rows, opt, source_types)
    if fmt=='at': return at_md_output(cols, rows, opt, False)
    if fmt=='md': return at_md_output(cols, rows, opt, True)
    if fmt=='vf': return vf_output(cols, rows, opt)
    return csv_output(cols, rows, opt, opt.bool.get('oh'))


def guess_output_format_from_out(opt: Opt):
    if opt.output_explicit or opt.bool.get('out-without-guess') or not opt.str.get('out'):
        return
    p=opt.str['out'].lower()
    # if compressed, guess from the name before compression suffix
    for suf in ('.gz','.bz2','.xz'):
        if p.endswith(suf): p=p[:-len(suf)]
    if p.endswith('.jsonl') or p.endswith('.ndjson'): opt.output_format='jsonl'
    elif p.endswith('.json'): opt.output_format='json'
    elif p.endswith('.ltsv'): opt.output_format='ltsv'
    elif p.endswith('.md') or p.endswith('.markdown'): opt.output_format='md'
    elif p.endswith('.tbln'): opt.output_format='tbln'
    elif p.endswith('.yaml') or p.endswith('.yml'): opt.output_format='yaml'
    elif p.endswith('.csv'): opt.output_format='csv'


def write_output(s: str, opt: Opt):
    path=opt.str.get('out','')
    if not path:
        sys.stdout.write(s); return
    oz=opt.str.get('oz','')
    if oz=='gz' or path.endswith('.gz'):
        with gzip.open(path,'wt',newline='') as f: f.write(s)
    elif oz=='bz2' or path.endswith('.bz2'):
        with bz2.open(path,'wt',newline='') as f: f.write(s)
    elif oz=='xz' or path.endswith('.xz'):
        with lzma.open(path,'wt',newline='') as f: f.write(s)
    else:
        with open(path,'w',newline='') as f: f.write(s)


def file_type_name(path: str, opt: Opt) -> str:
    return guess_format(path,opt).upper().replace('JSON','JSON').replace('YAML','YAML')


def analyze(path: str, opt: Opt, examples_only: bool) -> int:
    try:
        cols, rows, types = load_data_for_spec(path,opt)
    except Exception as ex:
        sys.stderr.write(f'{nowlog()} ERROR: {ex}\n')
        return 1
    sample = rows[:max(1,opt.integer.get('ir',1))]
    exe=sys.argv[0]
    cols_s=', '.join(cols)
    examples=[]
    examples.append(f'{exe} "SELECT {cols_s} FROM {path}"')
    if cols:
        val = cell_to_str(sample[0][0] if sample and sample[0] else '', opt).replace("'", "''")
        examples.append(f'{exe} "SELECT {cols_s} FROM {path} WHERE {cols[0]} = \'{val}\'"')
        examples.append(f'{exe} "SELECT {cols[0]}, count({cols[0]}) FROM {path} GROUP BY {cols[0]}"')
        examples.append(f'{exe} "SELECT {cols_s} FROM {path} ORDER BY {cols[0]} LIMIT 10"')
    if examples_only:
        sys.stdout.write('\n'.join(examples)+'\n')
        return 0
    sys.stdout.write(f'The table name is {path}.\n')
    sys.stdout.write(f'The file type is {file_type_name(split_table_spec(path)[0],opt)}.\n\n')
    sys.stdout.write('Data types:\n')
    dtype_cols=['column name','type']
    dtype_rows=[(c, 'text' if types.get(c,'text')=='text' else ('int' if types.get(c)=='integer' else types.get(c,'text'))) for c in cols]
    # local render without opt's output format
    tmp=Opt(); tmp.output_format='at'
    sys.stdout.write(at_md_output(dtype_cols, dtype_rows, tmp, False)+'\n')
    sys.stdout.write('Data samples:\n')
    sys.stdout.write(at_md_output(cols, sample[:1], tmp, False)+'\n')
    sys.stdout.write('Examples:\n')
    sys.stdout.write('\n'.join(examples)+'\n')
    return 0


def main(argv: List[str]) -> int:
    opt, code = parse_args(argv)
    if opt is None:
        return code
    if opt.bool.get('version'):
        print('trdsql version devel')
        return 0
    if opt.bool.get('help'):
        print_usage(sys.stdout)
        return 2
    if opt.bool.get('dblist'):
        return 0
    if opt.str.get('A'):
        return analyze(opt.str['A'], opt, True)
    if opt.str.get('a'):
        return analyze(opt.str['a'], opt, False)
    query=''
    if opt.str.get('q'):
        try:
            with open(opt.str['q'],'r') as f: query=f.read()
        except FileNotFoundError:
            sys.stderr.write(f'{nowlog()} ERROR: open {opt.str["q"]}: no such file or directory\n')
            return 1
        except Exception as ex:
            sys.stderr.write(f'{nowlog()} ERROR: {ex}\n')
            return 1
    elif opt.str.get('t'):
        query=f'SELECT * FROM {opt.str["t"]}'
    elif opt.args:
        query=opt.args[0]
    else:
        print_usage(sys.stdout)
        return 2
    guess_output_format_from_out(opt)
    try:
        cols, rows, source_types, rewritten = fetch_query(query, opt)
        s=render(cols, rows, opt, source_types)
        write_output(s,opt)
        return 0
    except RuntimeError as ex:
        sys.stderr.write(f'{nowlog()} {ex}\n')
        return 1
    except Exception as ex:
        sys.stderr.write(f'{nowlog()} ERROR: {ex}\n')
        return 1

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
